  ['development','http://127.0.0.1:4187','**/src/styles.css'],
  ['production','http://127.0.0.1:4188','**/assets/*.css'],
]) {
  const page = await browser.newPage({viewport:{width:1440,height:900},colorScheme:'light'});
  await page.goto(`${origin}/members/1`);
  await page.locator('.app-shell').waitFor();
  const initialDocument = await page.evaluate(()=>performance.timeOrigin);
  let releaseCss, cssRequested;
  const waitingForCss = new Promise(resolve=>{cssRequested=resolve;});
  const gate = new Promise(resolve=>{releaseCss=resolve;});
  await page.route(cssPattern,async route=>{cssRequested();await gate;await route.continue();});
  await Promise.all([
    page.waitForURL(`${origin}/`,{waitUntil:'commit'}),
    page.getByRole('link',{name:'Back to search',exact:true}).click({noWaitAfter:true}),
  ]);
  await waitingForCss;
  const beforeCss = await page.evaluate(()=>({background:getComputedStyle(document.documentElement).backgroundColor,scheme:getComputedStyle(document.documentElement).colorScheme,document:performance.timeOrigin}));
