  await page.screenshot({path:`/tmp/exposed-dark-navigation-${name}-loaded.png`});
  console.log(`${name}: black background and dark scheme before CSS, new document navigation preserved, app loads successfully`);
  await page.close();
}
} finally {await browser.close();}
